<?php require 'config.php';require 'includes/functions.php';require_login();$s=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC");$s->execute([current_user()['id']]);$orders=$s->fetchAll();$title='My account';require 'includes/header.php';?><div class="page-head"><span class="eyebrow">YOUR STYLEHUB</span><h1>Hello, <?=e(current_user()['name'])?>.</h1><p><?=e(current_user()['email'])?></p></div><section class="panel"><h2>Order history & tracking</h2><?php if(!$orders):?><p>No orders yet. <a href="index.php">Start shopping</a>.</p><?php else:?><div class="table-scroll"><table><tr><th>Order</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th><th>Details</th></tr><?php foreach($orders as $o):?><tr><td>#SH<?=str_pad((string)$o['id'],5,'0',STR_PAD_LEFT)?></td><td><?=e($o['created_at'])?></td><td><?=money($o['total_amount'])?></td><td><?=e($o['payment_status'])?></td><td><?=e($o['status'])?></td><td><a href="order.php?id=<?=$o['id']?>">View</a></td></tr><?php endforeach;?></table></div><?php endif;?></section><?php require 'includes/footer.php';?>